  function resetOptimisticMessages(){lastDurableMessages=[];optimisticPrompts=[];latestUserTextCounts=new Map();awaitingTurnStartedAt=0;agentRunning=false;currentTodos=[];todoExpanded=false;renderTodoDock()}
  function showSessionList(){clearTimeout(poll);poll=null;closeSessionSettings();activeSession=null;resetOptimisticMessages();syncPendingQuestion(null);document.body.classList.remove('chat-open');$('chatView').classList.remove('active');$('sessionsView').classList.add('active');loadSessions()}
  async function openSession(id,title,fromHistory=false){clearTimeout(poll);if(!fromHistory)history.pushState({view:'chat',sessionId:id,title:title||L.untitled},'');activeSession=id;const summary=sessionSummaries.find(item=>item.sessionId===id);sessionBlank=summary?.blank??true;currentPreset=summary?.agentPreset||null;modelCatalog=null;closeSessionSettings();lastHistoryKey='';resetOptimisticMessages();syncPendingQuestion(null);document.body.classList.add('chat-open');$('sessionsView').classList.remove('active');$('chatView').classList.add('active');$('messages').innerHTML='<div class="loading"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div>';await loadHistory(true);schedulePoll()}
